def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c

    last_me, last_op = history[-1]

    # opponent defection streak at end
    op_def_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            op_def_streak += 1
        else:
            break

    # opponent cooperation streak at end
    op_c_streak = 0
    for a, b in reversed(history):
        if b == 'C':
            op_c_streak += 1
        else:
            break

    # recent window (last 8)
    w = 8 if n >= 8 else n
    recent = history[-w:]
    recent_opp_c = 0
    for a, b in recent:
        if b == 'C':
            recent_opp_c += 1
    recent_opp_rate = recent_opp_c / w

    rounds_left = 100 - n

    # First move: cooperate
    if n == 1:
        # brief retaliation against immediate defection
        if last_op == 'D':
            return 'D'
        return 'C'

    # Endgame
    if rounds_left <= 1:
        # last round: if opponent likely cooperates, defect
        if recent_opp_rate >= 0.5 or op_c_streak >= 1:
            return 'D'
        return 'D'

    if rounds_left <= 3:
        if recent_opp_rate >= 0.6:
            return 'D'
        if recent_opp_rate <= 0.3:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # If opponent basically never defects, cooperate but exploit at very end
    if opp_d == 0:
        if rounds_left <= 2:
            return 'D'
        return 'C'

    # If opponent is heavily defecting, defect with occasional forgive
    if op_def_streak >= 4:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    if opp_d * 2 > n and recent_opp_rate < 0.4:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    if op_def_streak >= 2:
        if recent_opp_rate < 0.35:
            return 'D'
        # try to restart cooperation sometimes after a short clash
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent defected last round but not a streak
    if last_op == 'D':
        if recent_opp_rate >= 0.6:
            # likely noise/isolated, forgive
            return 'C'
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if opp_d * 3 < n and recent_opp_rate >= 0.85:
        # mostly nice opponent: rare probe to exploit
        if rounds_left > 10 and rng.random() < 0.07:
            return 'D'
        return 'C'

    if recent_opp_rate >= 0.5:
        return 'C'

    if rng.random() < 0.25:
        return 'D'
    return 'C'
